import{_ as o,l,o as e,c as i,v as r,p as s,x as t,d as h,i as p,S as d}from"./chunks/framework.InCnrqk-.js";const k=JSON.parse('{"title":"业绩持续性","description":"","frontmatter":{"title":"业绩持续性","date":"2026-09-08T00:00:00.000Z","section":"quant"},"headers":[],"relativePath":"quant/performance-persistence.md","filePath":"quant/performance-persistence.md","lastUpdated":1789023840000}'),c={name:"quant/performance-persistence.md"};function m(E,a,u,B,_,A){const n=l("Mermaid");return e(),i("div",null,[a[1]||(a[1]=r('<h1 id="业绩持续性" tabindex="-1">业绩持续性 <a class="header-anchor" href="#业绩持续性" aria-label="Permalink to &quot;业绩持续性&quot;">​</a></h1><div class="epigraph"><p>扣费后，共同基金的业绩持续性大部分被动量与费用解释掉；剩下的「热手」很弱，且会被资金流冲淡。</p><footer>—— Carhart, On Persistence in Mutual Fund Performance, Journal of Finance, 1997；技能与运气见 Fama and French, Journal of Finance, 2010</footer></div><p><a href="/quant/fees-compounding">上一课</a>说明费用确定地吃复利。持续性的缺口是：<strong>扣费后的超额会不会重复</strong>。Carhart 用四因子（市场、规模、价值、动量，见 <a href="/quant/carhart4">Carhart 四因子</a>）表明：一年期的「赢家基金」持续性很大一块是股票动量加上费用差异，不是稳定的选股 alpha。Fama–French（2010）用 bootstrap 问：行业里有多少基金的 alpha 超出运气。Berk–Green 把持续性弱写成均衡：技能会吸引资金直到净 alpha 为零。本课不重做截面定价实证，只把这些结论接到产品评价。</p><h2 id="问题" tabindex="-1">问题 <a class="header-anchor" href="#问题" aria-label="Permalink to &quot;问题&quot;">​</a></h2><p>投资人选基金就是在做因子择时加选经理。若持续性只来自未扣的动量暴露，买「去年前十分位」等于买拥挤动量。问题是分层：毛 alpha、净 alpha、暴露调整后的残差。Kosowski、Timmermann、Wermers、White 的 bootstrap 显示右尾可能有技能，但可投资性还要过容量与后课资金流。对冲基金样本有存活偏差与回填，持续性更容易被高估。</p><p>与生命周期：策略衰减是信号层；基金持续性是产品层。一只基金可以换信号继续活，持续性仍可以断。</p><h3 id="运气的零假设要含费用" tabindex="-1">运气的零假设要含费用 <a class="header-anchor" href="#运气的零假设要含费用" aria-label="Permalink to &quot;运气的零假设要含费用&quot;">​</a></h3><p>把净收益对因子回归得到 \\(\\hat\\alpha\\)，再问是否大于零。零假设若不管费用，平庸经理也会因为费率为正而 \\(\\alpha\\lt 0\\)。Fama–French 的「技能」是相对净 alpha 的横截面：真正的问题是右尾是否厚过运气。不要用单只三年夏普宣称技能，见后课抽样误差。</p><p><span class="marginnote">排序期与持有期若重叠，或用同一段动量因子两边解释，会制造假持续性。Carhart 的贡献之一就是把动量从「经理技能」里拿出来。</span></p><h2 id="方法" tabindex="-1">方法 <a class="header-anchor" href="#方法" aria-label="Permalink to &quot;方法&quot;">​</a></h2><p>排序：过去 1 年净收益或净 alpha → 随后持有期。控制：四因子暴露、费用份额、规模。稳健：发表后子样本、存活偏差处理。对冲基金：用报告频率与锁定期对齐，不可用月频平滑当低波动技能。</p><h2 id="机制" tabindex="-1">机制 <a class="header-anchor" href="#机制" aria-label="Permalink to &quot;机制&quot;">​</a></h2><p>若技能存在且资金有限，净 alpha 可暂为正。资金追逐（下课）把 AUM 推到技能的容量上限，净 alpha 被摊薄到零（Berk–Green）。费用提高摊薄速度。动量使短期排序看起来像技能。于是可投资的持续性短、弱、容量小。</p>',13)),(e(),s(d,null,{default:t(()=>[p(n,{id:"mermaid-37",class:"mermaid",graph:"flowchart%20TD%0A%20%20Past%5B%22%E8%BF%87%E5%8E%BB%E5%87%80%E6%94%B6%E7%9B%8A%22%5D%20--%3E%20Mom%5B%22%E8%82%A1%E7%A5%A8%E5%8A%A8%E9%87%8F%22%5D%0A%20%20Past%20--%3E%20Fee%5B%22%E8%B4%B9%E7%94%A8%E5%B7%AE%E5%BC%82%22%5D%0A%20%20Past%20--%3E%20Skill%5B%22%E6%AE%8B%E5%B7%AE%E6%8A%80%E8%83%BD%22%5D%0A%20%20Skill%20--%3E%20Flow%5B%22%E8%B5%84%E9%87%91%E6%B5%81%E5%85%A5%E6%91%8A%E8%96%84%22%5D%0A%20%20Mom%20--%3E%20Weak%5B%22%E5%8F%AF%E6%8A%95%E8%B5%84%E6%8C%81%E7%BB%AD%E6%80%A7%E5%BC%B1%22%5D%0A%20%20Flow%20--%3E%20Weak%0A"})]),fallback:t(()=>[...a[0]||(a[0]=[h(" Loading... ",-1)])]),_:1})),a[2]||(a[2]=r('<h2 id="边界" tabindex="-1">边界 <a class="header-anchor" href="#边界" aria-label="Permalink to &quot;边界&quot;">​</a></h2><p>本课不给「如何选到未来前十分位」的清单。私募与封闭结构改变流量机制，结论不能直接搬。下一课专门写流。</p><h2 id="小结" tabindex="-1">小结 <a class="header-anchor" href="#小结" aria-label="Permalink to &quot;小结&quot;">​</a></h2><ul><li>扣费后共同基金持续性大部分是动量与费用，不是稳定 alpha。</li><li>技能若存在，会被资金流摊薄（Berk–Green）。</li><li>单只短样本夏普不够当技能证据。</li><li>出处：Carhart, <em>JF</em>, 1997；Fama and French, <em>JF</em>, 2010；Berk and Green, <em>JPE</em>, 2004。</li></ul>',4))])}const q=o(c,[["render",m]]);export{k as __pageData,q as default};
